    await expect(pg_uma.getByTestId("header-overdue-total")).toHaveText("0.00");
    await expect(pg_uma.getByTestId("my-due-total")).toHaveText("0.00");
    await expect(pg_uma.getByTestId("my-overdue-total")).toHaveText("0.00");
