      `TOTALS sheet=${sheet} by=uma claimed-total=10.00 due-total=2.00 overdue-total=0.00`,
      `CLAIM_OPENED sheet=${sheet} by=uma person=uma amount=20.00 date=2026-03-10 number=2`,
